from SSHLibrary import SSHClient
from time import sleep
from robot.utils.robottime import timestr_to_secs

from ute_common_store import Store
from ute_common_converter.to_number import to_int
from ute_common_interface.scope import ScopeController
from ute_common_util.decorators.retry import retry_until_no_exception_or_out_of_attempts

from ute_tshark.counting import CountingPackets
from ute_tshark.capturing import SavingPackets


class ute_tshark(ScopeController):
    """Class provide mechanism for packets capturing on local or remote machine interface.

       This library supports multiple setups where each setup can be specified by **alias** argument for every keyword.

       This argument can be specified as follows:
       ::

           Setup Tshark  interface=${ENB_TRS_INTERFACE}  log_dir=/home/ute  log_name=tshark_example_02  alias=example_02_eth3

       More examples are available in attached Robot Framework example files.


    Keywords
    ********
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        super(ute_tshark, self).__init__()
        self.store = Store()
        self.ssh_client = None

    def setup_tshark(self, interface,
                     log_dir='/tmp',
                     log_name=None,
                     snaplen=65535,
                     pcap_size=None,
                     tshark_dir='/usr/bin',
                     preferences=None,
                     ssh_ip='localhost',
                     ssh_username='ute',
                     ssh_password='ute',
                     ssh_port=22,
                     ssh_prompt='$ ',
                     encoding='unicode-escape',
                     **kwargs):

        """Setup tshark library

        Library is working through SSH connection. Localhost is used as default destination.


        :param string interface:        Local or remote virtual machine interface which is used to packects capture.
        :param string log_dir:          Directory name where pcap file is stored.
        :param string log_name:         File name where packets are stored.
        :param integer snaplen:         Amount of data for each frame that is captured.
        :param string tshark_dir:       Path to dictionary where tshark is located.
        :param string preferences:      Preference setting to be overridden.
        :param string ssh_ip:           IP address of remote machine.
        :param string ssh_username:     Username for SSH authentication valid for remote machine.
        :param string ssh_password:     Password for SSH authentication valid for remote machine.
        :param integer ssh_port:        Port of SSH service available on remote machine.
        :param string ssh_prompt:       SSH prompt available after log in.
        :param string encoding:         Encoding to be used by SSH.
        """
        if self._encoding_exists():
            ssh_client = SSHClient(ssh_ip, port=ssh_port, prompt=ssh_prompt, timeout=10, encoding=encoding)
        else:
            ssh_client = SSHClient(ssh_ip, port=ssh_port, prompt=ssh_prompt, timeout=10)
        ssh_client = self._attempt_ssh_client_login(ssh_client, ssh_username, ssh_password, ssh_prompt)
        tsharks = self._build_dict_with_tsharks(ssh_client, tshark_dir, interface, log_dir, log_name, snaplen, pcap_size, preferences)
        self.store.add(tsharks, alias=kwargs.get('alias'))

    def teardown_tshark(self, **kwargs):
        """Close and Cleanup tshark.
        """
        self._cleaner(self.store.get(alias=kwargs.get('alias')))
        self.store.remove(alias=kwargs.get('alias'))

    def teardown_all_aliases_for_tshark(self):
        """Close and Cleanup all tshark aliases.
        """
        self._out_of_scope()

    def start_capturing(self, capture_filter='', log_dir=None, log_name=None, **kwargs):
        """Start collecting logs with capture filter.

        :param string capture_filter:   Capture filter definition       (equivalent -f in tshark).
        :param string log_dir:          Replaces log_dir passed in setup tshark until stop capturing KW is called
        :param string log_name:         Replaces log_name passed in setup tshark until stop capturing KW is called

        """
        self.store.get(alias=kwargs.get('alias'))['saving'].start_logging(capture_filter, log_dir, log_name)

    def capture_packets_for_given_seconds(self, seconds, capture_filter='', log_dir=None, log_name=None, **kwargs):
        """Start collecting logs with capture filter and wait until command execution finish.

        :param string seconds:          Time duration of tshark execution (tshark -a duration:<seconds> equivalent).
        :param string capture_filter:   Capture filter definition       (equivalent -f in tshark).
        :param string log_dir:          Replaces log_dir passed in setup tshark until stop capturing KW is called
        :param string log_name:         Replaces log_name passed in setup tshark until stop capturing KW is called

        """
        self.store.get(alias=kwargs.get('alias'))['saving'].capture_packets_for_given_seconds(seconds, capture_filter, log_dir, log_name)

    def capture_given_packet_count_and_wait(self, packets, timeout=30, capture_filter='', log_dir=None, log_name=None, **kwargs):
        """Start capturing packets and wait until given packets are captured.

        :param string packets:          Number of packets to capture (tshark -c equivalent).
        :param string timeout:          Time duration for packet capture (tshark -a duration:<seconds> equivalent).
        :param string capture_filter:   Capture filter definition   (tshark -f equivalent).
        :param string log_dir:          Directory name where pcap file is stored.
        :param string pcap_name:        File name where packets are stored.

        """
        self.store.get(alias=kwargs.get('alias'))['saving'].capture_given_packet_count_and_wait(packets, timeout, capture_filter, log_dir, log_name)

    def stop_capturing(self, **kwargs):
        """Stop collecting logs.

        """
        self.store.get(alias=kwargs.get('alias'))['saving'].stop_logging()

    def start_counting_packets(self, packet_filter, **kwargs):
        """Start counting packets with given packet filter.

        :param string packet_filter:        Packet filter definition       (equivalent -Y in tshark).

        """
        self.store.get(alias=kwargs.get('alias'))['counting'].start_counting(packet_filter)

    def stop_counting_packets(self, **kwargs):
        """Stop counting packets.

        """
        self.store.get(alias=kwargs.get('alias'))['counting'].stop_counting()

    def wait_for_given_packets_number(self, packet_number, timeout=120, **kwargs):
        """Wait until given packets are captured.

        :param integer packet_number:   Maximum number of packets to be captured.
        :param integer timeout:         Maximum number of seconds to wait for a given number of packets are captured.

        :raise: exception if captured packets are not equal packet_number before timeout.
        """

        timeout = timestr_to_secs(timeout)
        packet_number = to_int(packet_number)
        self.store.get(alias=kwargs.get('alias'))['counting'].wait_for_packets(packet_number, timeout)

    def read_pcap(self, packet_filter='', output_type='text', pcap_file_path=None, decode_as=None, fields=None, **kwargs):
        """Read pcap file and return it as string.

        :param string packet_filter:    Deep packet filter definition       (tshark -Y equivalent).
        :param string output_type:      Output form e.g pdml/text/lines     (tshark -T equivalent).
        :param string decode_as:        Decode as protocol                  (tshark -d equivalent)
        :param string pcap_file_path:   Pcap file path.
        :param list fields:             Field options to be read            (tshark -e equivalent).

        :return:                        Packets matched with packet filter rules.
        :rtype:                         string
        """
        return self.store.get(alias=kwargs.get('alias'))['saving'].read_pcap(packet_filter, output_type, pcap_file_path,
                                                                             decode_as, fields)

    def read_pcap_and_save_to_file(self, filename, packet_filter='', output_type='text', pcap_file_path=None, decode_as=None, **kwargs):
        """Read pcap file and save it to file

        :param string filename:         Output file name
        :param string packet_filter:    Deep packet filter definition       (tshark -Y equivalent).
        :param string output_type:      Output form e.g pdml/text/lines     (tshark -T equivalent).
        :param string decode_as:        Decode as protocol                  (tshark -d equivalent)
        :param string pcap_file_path:   Pcap file path.
        """
        pcap_decoded = self.store.get(alias=kwargs.get('alias'))['saving'].read_pcap(packet_filter, output_type, pcap_file_path,
                                                                                     decode_as,)
        with open(filename, 'wb') as f:
            f.write(pcap_decoded.encode('utf-8'))

    def download_pcap_file(self, destination, **kwargs):
        """Copy pcap file from the remote host to the specified destination path in the local machine.

        :param string destination:          Destination file path.

        :return:                            Source and destination path.
        :rtype:                             tuple
        """
        return self.store.get(alias=kwargs.get('alias'))['saving'].download_pcap(destination)

    def get_packets_count(self, packet_filter='', pcap_file_path=None, **kwargs):
        """Returns number of packets matched with the packet filter.

        :param string packet_filter:    Deep packet filter definition       (tshark -Y equivalent).
        :param string pcap_file_path:   Pcap file path.

        :return :                       Number of packets matched with packet filter rules.
        :rtype:                         integer

        """
        output = self.store.get(alias=kwargs.get('alias'))['saving'].read_pcap(packet_filter, 'lines', pcap_file_path)
        captured_packets = output.rstrip().split('\n')
        return int(len([packet for packet in captured_packets if packet]))

    def get_packet_number(self, **kwargs):
        """ Get number of packets collected by start_counting method.

        :return integer:        Amount of captured packets.
        :rtype:                 integer
        """
        return self.store.get(alias=kwargs.get('alias'))['counting'].get_packet_number()

    def lookup_message_flow(self, messages, pcap_file_path=None, **kwargs):
        """Search for messages in pcap file read in pdml format. Returns true if order and duplication is correct.

        :param list messages:                messages that will be checked.
        :param string pcap_file_path:        Pcap file path where messages will be searched.

        :return boolean:                True if messages are found in order and correct frequency else False.

        """
        return self.store.get(alias=kwargs.get('alias'))['saving'].lookup_message_flow(messages, pcap_file_path)

    def lookup_messages_in_fields(self, message, fields, packet_filter='', pcap_file_path=None, **kwargs):
        """ Look up certain messages in the given field columns

        :param string messages:              messages that will be looked for.
        :param list fields                   list of field options
        :param string packet_filter          Deep packet filter definition.
        :param string pcap_file_path         Pcap file path where messages will be searched.

        :return:                     Packets matched with packet filter rules and the look up message
        :rtype:                      string

        """

        return self.store.get(alias=kwargs.get('alias'))['saving'].lookup_messages_in_fields(message, fields, packet_filter, pcap_file_path)

    def _encoding_exists(self):
        return 'encoding' in SSHClient.__init__.__code__.co_varnames

    def _cleaner(self, tsharks):
        for tshark in tsharks.values():
            if tshark.pid is not None:
                tshark.stop_process()

    def _build_dict_with_tsharks(self, ssh_client, tshark_dir, interface, log_dir, log_name, snaplen, pcap_size, preferences):
        tsharks_dict = {'saving': SavingPackets(ssh_client, tshark_dir, interface, log_dir, log_name, snaplen, pcap_size, preferences),
                        'counting': CountingPackets(ssh_client, tshark_dir, interface, log_dir, snaplen, preferences)}
        return tsharks_dict

    @retry_until_no_exception_or_out_of_attempts(3)
    def _attempt_ssh_client_login(self, ssh_client, ssh_username, ssh_password, ssh_prompt):
        if 'look_for_keys' in ssh_client.login.__code__.co_varnames:
            ssh_client.login(ssh_username, ssh_password, look_for_keys=True)
        else:
            ssh_client.login(ssh_username, ssh_password)
        return ssh_client

    def _out_of_scope(self):
        """Method will define set of actions to clean-up library."""
        for key in self.store.aliases:
            self.teardown_tshark(alias=key)
